/**
 * Typed access to src/data/unpartyRefsManifest.json, the manifest behind the
 * unparty button (/admin/unparty): every remaining reference to unparty — the
 * brand, not the frame — grouped by category so a buyer can replace each one
 * (#1095). Generated by scripts/generate-unparty-refs.js on every build; the
 * decisions (what counts, the unppp vocabulary allowlist, delete-don't-rename
 * for example pages) are documented in that script's header.
 *
 * Deliberately does NOT import the manifest JSON (it is large): only the API
 * route reads it. This module stays safe to import from client components.
 */

/** [line, match] with an occurrences count appended when a line repeats it */
export type UnpartyRefLine = [number, string] | [number, string, number];

export interface UnpartyRefFile {
  file: string;
  count: number;
  /** line 0 means the match is in binary file metadata, not a text line */
  lines: UnpartyRefLine[];
}

export type UnpartyRefCategoryId = 'identity' | 'domain' | 'projects' | 'author';

export interface UnpartyRefCategory {
  id: UnpartyRefCategoryId;
  label: string;
  description: string;
  order: number;
  files: number;
  matches: number;
  entries: UnpartyRefFile[];
}

export interface UnpartyRefsManifest {
  generatedAt: string;
  /** GitHub repo URL when detectable at build time, for file/line links */
  repo: string | null;
  branch: string;
  /** false when git could not list the files (no .git); nothing was counted */
  measured: boolean;
  /** why it was not measured */
  reason?: string;
  /** true when no references remain outside the allowlist - the step is done */
  done: boolean;
  total: { files: number; matches: number; paths: number };
  /** unppp is frame vocabulary a buyer keeps; informational, never counted */
  vocabulary: { pattern: string; kept: boolean; note: string; files: number; matches: number };
  /** frame files (replacement tooling, curriculum, license) never counted */
  allowlist: string[];
  categories: UnpartyRefCategory[];
  /** tracked file paths containing "unparty" - count toward done; deleted or replaced, pages never renamed */
  paths: string[];
}

/**
 * The unparty button's admin nav entry. Lives here (an allowlisted frame
 * file) so the nav keeps zero reachable: the tool that erases the brand must
 * not hard-code it anywhere a buyer would have to edit.
 */
export const UNPARTY_BUTTON = { href: '/admin/unparty', label: 'UNPARTY' } as const;
